def word_frequency(text: str) -> dict[str, int]:
    import string
    freq = {}
    for w in text.split():
        clean = w.strip(string.punctuation)
        if clean:
            clean = clean.lower()
            freq[clean] = freq.get(clean, 0) + 1
    return freq
